export function install(ctx){
 function quickRecordDialog(type,onSaved,prefill=null,context='orçamento'){const client=type==='clients';if(!ctx.can(type,'create'))return ctx.toast('Seu acesso não permite esse cadastro.');const d=ctx.modal('Cadastrar '+(client?'cliente':'produto')+' sem sair do '+ctx.esc(context),`<form><div class="grid2">${client?`<label class="field">Tipo<select name="kind"><option value="PF">Pessoa física</option><option value="PJ">Pessoa jurídica</option></select></label>${ctx.field('Nome / razão social','name','text','','required minlength="2" maxlength="200"')}${ctx.field('CPF / CNPJ','document','text','','maxlength="20"')}${ctx.field('Telefone / WhatsApp','phone','tel','','maxlength="25"')}${ctx.field('E-mail','email','email','','maxlength="200"')}${ctx.field('Endereço','address','text','','maxlength="500"')}`:`${ctx.field('Nome do produto','name','text','','required minlength="2" maxlength="200"')}<label class="field">Código automático<input value="Gerado ao salvar" disabled></label>${ctx.field('Referência interna (opcional)','reference','text','','maxlength="80"')}${ctx.field('Custo unitário (R$)','cost','number','','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de varejo (R$)','retail','number','0','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de atacado (R$)','wholesale','number','0','required min="0" max="9999999999" step="0.01"')}`}</div><p class="note">O formulário de origem permanece preenchido. O novo cadastro será selecionado assim que você salvar.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Salvar ${client?'cliente':'produto'}</button></div></form>`,{wide:true});if(client){ctx.addDocumentLookup(d.querySelector('form'),{type:'clients'});if(prefill)ctx.fillContact(d.querySelector('form'),prefill)}if(!client&&prefill)for(const name of ['name','reference','cost','retail','wholesale']){const input=d.querySelector('form').elements.namedItem(name);if(input&&prefill[name]!=null)input.value=prefill[name]}d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));if(client){const existing=ctx.existingDocument('clients',body.document);if(existing){d.close();await onSaved?.(existing);ctx.toast('Cliente já cadastrado e selecionado.');return}}if(!client)for(const k of ['cost','retail','wholesale'])body[k]=Number(body[k]);const result=await ctx.api('/rest/v1/'+type,{method:'POST',body,headers:{Prefer:'return=representation'}});await ctx.load();d.close();await onSaved?.(result[0]);ctx.toast(client?'Cliente cadastrado e selecionado.':'Produto '+result[0].sku+' cadastrado e selecionado.')}catch(err){d.querySelector('.error').textContent=err.message;e.submitter.disabled=false}};
 }
 Object.assign(ctx,{quickRecordDialog});
}
